// Shared table-export helpers. Previously copy-pasted verbatim into
// listAllCases.vue, result.vue and assigning.vue. Pure functions — no `this`.
//
// `fieldsMap` maps a human column label to the row property name, e.g.
//   { "姓名": "name", "學號": "caseId" }

// One CSV row (array of cell values) for a record, in fieldsMap order.
export function buildRow(item, fieldsMap) {
  return Object.keys(fieldsMap).map(label => item[fieldsMap[label]])
}

// Full CSV content (header + rows) as a data: URI, matching the previous
// hand-rolled output exactly (CRLF line breaks, comma-joined).
export function buildCSVContent(rows, fieldsMap) {
  const csvRows = [Object.keys(fieldsMap)]
  rows.forEach(item => csvRows.push(buildRow(item, fieldsMap)))
  return 'data:text/csv;charset=utf-8,' + csvRows.map(r => r.join(',')).join('\r\n')
}

// Trigger a browser download of the rows as CSV.
export function downloadCSV(rows, fieldsMap) {
  window.open(encodeURI(buildCSVContent(rows, fieldsMap)))
}

// "星期<day> <time>" label for an assigned case, given the day/time lookup
// tables from weektimeMixin. Falls back to a placeholder if a code is unknown.
export function formatConsultationDateTime(caseItem, days, times) {
  const dayMatch = days.find(e => e.value == caseItem.consultation_day)
  const timeMatch = times.find(e => e.value == caseItem.consultation_time)
  const dayLabel = dayMatch ? dayMatch.label : 'Unknown day'
  const timeLabel = timeMatch ? timeMatch.label : 'Unknown time'
  return '星期' + dayLabel + ' ' + timeLabel
}
