<template lang="pug">
.page-container
    .page-title-container
        .flex-half
            .page-title 尚待派案學生列表
            div
                span 派案學期：
                select.labelSelector(v-model='semesterLabel' @change='semesterLabelSelected()')
                    option(value='') 請選擇或輸入學期標籤
                    option(v-for='option in labelOption' :key='option.label' :value='option.label') {{ option.label }}
            //-     span 排序方式：
            //-     el-select(v-model="sortRule" placeholder="請選擇排序方式" @change="pushSortRule()")
            //-         el-option(key="crisis_level" label="危機程度優先" value="crisis_level")
            //-         el-option(key="time" label="初談時間優先" value="time")
        .flex-half(style="padding-left: 7px")
            div
                span.page-title 初排結果
                el-popover(placement="bottom" title="" :width="400" trigger="hover")
                    strong 操作方式
                    div 拖曳左側為派案個案、或是灰色實心方塊調整心理師與時段
                    br
                    strong 方塊顏色意義
                    div 灰色空格：心理師此時段為有空
                    div 灰色實心：初排將此時段配對到一個新的個案
                    div 藍色實心：心理師此時段已有排到個案，並且諮商次數為0~6次
                    div 紅色實心：心理師此時段已有排到個案，並且諮商次數為7~14次
                    div 紫色實心：心理師此時段已有排到個案，並且諮商次數為15次以上
                    template(#reference)
                        span.timetable-info 操作說明
                            InfoFilled(style="width: 1em; height: 1em; padding: 0 0 0 3px")
            .assign-save(style="padding: 17px 0")
                el-button(size="large" type="warning" @click="submitChange()") 儲存修改
    el-row(:gutter="10" v-loading="loading")
        el-col(:sm="24" :md="12")
            .drag-table(@drop="drop" @dragover="allowDrop" class="drag-container" ref="dragBody" id="dragBody")
                .drag-hint 共 {{unassignCases.length}} 筆待派，可拖曳個案卡片至右側時段
                .case-card(v-for="item in unassignCases" :key="item.id" :draggable="item.status=='unassign'" @dragstart="drag" :id="'drag-'+item.id" :class="item.status=='unassign'?'case-card-draggable':'case-card-disabled'")
                    .case-card-head
                        span.case-card-name {{item.name}}
                        span.case-card-id {{item.caseId}}
                        span.crisis-badge(:class="crisisBadgeClass(item.crisis_level)") {{item.crisis_level}}
                    .case-card-tags
                        SemesterLabelTag(:label="item.semester_label")
                        el-tag(size="small" type="info" effect="plain") 性別：{{item.preferred_gender || '不限'}}
                        el-tag(size="small" :type="internDispatchable(item) ? 'info' : 'warning'" effect="plain") {{internDispatchable(item) ? '可派實習生' : '不可派實習生'}}
                        el-tag(size="small" :type="item.designated_counselor_name ? 'success' : 'info'" effect="plain") 指定：{{item.designated_counselor_name || '無'}}
                    .case-card-row
                        span.case-card-label
                            | 可諮商時段
                            el-popover(placement="right" title="" :width="200" trigger="hover" popper-class="weektimePop")
                                div(v-html="getHtmlContent()")
                                template(#reference)
                                    QuestionFilled(style="width: 1em; height: 1em; padding: 0 0 0 3px")
                        span.case-card-value {{item.available_time}}
                    .case-card-row(v-if="item.discription && item.discription!='無'")
                        span.case-card-label 狀態
                        span.case-card-value {{item.discription}}
                    .case-card-row
                        span.case-card-label 初談時間
                        span.case-card-value {{convertUTCtoStr(item.init_consultation_date)}}
        el-col(:sm="24" :md="12")
            .assign-table(ref="assignTable")
                el-row.assign-header(:style="'width: '+tableWidth+'px'")
                    el-col(:span="3")
                        .slopeline
                            .slope-label.slope-label-1 姓名
                            .slope-label.slope-label-2 時段
                    el-col.assign-col-container(:span="21")
                        .row-bar.assign-header-label(:span="2" v-for="i in times") {{i.label.split('~')[0]}}
                el-row.assign-body
                    template(v-for="(day,tIdx) in dayList")
                        el-col(:span="24").assign-date {{getDatetime(day.offset)}}
                            el-tag(v-if="timetable[day.offset].isHoliday" type="danger" size="small" class="mx-1" effect="dark" round) 假日
                        template(v-for="(row,rowIdx) in timetable[day.offset].rows")
                            template(v-if="!timetable[day.offset].isHoliday")
                                el-col.assign-aside-label.col-bar(:span="3")
                                    div {{row.counselor_name}}
                                    el-tag(v-if="row.employment_type" size="small" type="info" effect="plain") {{row.employment_type}}
                                    el-tooltip(v-else-if="row.inSemester" content="未設定聘用類別，初排不會自動配對此心理師，請先至心理師管理編輯" placement="right")
                                        el-tag(size="small" type="danger" effect="plain") 未設定聘用類別
                                el-col.assign-col-container.col-bar(:span="21")
                                    .row-bar.unavailable(:span="2" v-for="i in times")
                                        timeBlock.drag-container(v-if="row.block[i.value]" :block='row.block[i.value]' 
                                            :pos="day.offset+'-'+rowIdx+'-'+i.value"
                                            @addTimeblock="addTimeblock($event,day.offset,rowIdx,i.value)" 
                                            @removeTimeblock="removeTimeblock"
                                            @setDragPos="setDragPos"
                                            @endCase="endCase($event,data)"
                                            @returnCase="returnCase($event,data)")
    el-dialog(title="儲存成功" v-model="dialogVisible" width="60%" @close="handleClose" center)
        el-row
            el-col(:span="12")
                h3 本次新增派案
            el-col(:span="12")
                download-excel(:data='downloadXLS()' :fields="json_fields" :name='getDateStr(0)+"新增派案.xls"')
                    el-button(type="success" style="float: right;margin-right: 40px;" ) 下載Excel
                el-button(type="success" style="float: right;margin-right: 40px;" @click="downloadCSV()") 下載CSV
        el-table(:data="assigningCases" style="width: 100%")
            el-table-column(prop="name" label="姓名")
            el-table-column(prop="caseId" label="學號")
            el-table-column(prop="semester_label" label="學期標籤")
            el-table-column(label="諮商時段")
                template(#header='')
                    el-popover(placement="right" title="" :width="200" trigger="hover" popper-class="weektimePop")
                        div(v-html="getHtmlContent()")
                        template(#reference)
                            span 諮商時段
                                QuestionFilled(style="width: 1em; height: 1em; padding: 0 0 0 3px")
                template(#default='scope')
                    div {{scope.row.consultation_day + scope.row.consultation_time}}
            el-table-column(prop="counselor_name" label="派案老師")
            el-table-column(prop="first_consultation_date" label="諮商開始時間")
            el-table-column(prop="crisis_level" label="危機程度")
            el-table-column(prop="init_counselor_name" label="初談老師")
            el-table-column(prop="discription" label="狀態說明")
            el-table-column(prop="init_consultation_date" label="初談時間")
                template(#default='scope')
                    div {{convertUTCtoStr(scope.row.init_consultation_date)}}
        .dialog-footer(slot="footer" style="text-align: center")
            el-button(type="danger" @click="dialogVisible = false") 關閉
</template>

<script>
import timeBlock from '@/views/assign/assigningBlock'
import {weektimeMixin} from "@/components/weektimeMixin"
import SemesterLabelTag from '@/components/SemesterLabelTag.vue';
import { downloadCSV as csvDownload, formatConsultationDateTime } from '@/utils/exportTable'
import { dateStrFromOffset } from '@/utils/date'
import { fitEmptyTimeList, clearRepeatTime, removeEmptyTimeList, buildMatchTree } from '@/utils/scheduling'
import { isEligible, EMPLOYMENT } from '@/utils/matchingRules'
import _ from "lodash"
export default {
    mixins: [weektimeMixin],
    components: {timeBlock, SemesterLabelTag},
    inject: ["reload"],
    data () {
        return {
            dialogVisible: false,
            // assigningCases: [],
            assignCases: [],
            unassignCases: [],
            timetable: {},
            counselorById: {},
            tableWidth: 0,
            dragPos: '',
            dayList: [],
            emptyTimeList: [],
            finalTimeInfo: [],
            loading: true,
            json_fields: {
                "姓名": "name",
                "學號": "caseId" ,
                "學期標籤": "semester_label",
                "諮商時段": "consultation_datetime",
                "派案老師": "counselor_name",
                "諮商開始時間": "first_consultation_date",
                "危機程度": "crisis_level",
                "初談老師": "init_counselor_name",
                "狀態說明": "discription",
                "初談時間": "init_consultation_date"
            },
            semesterLabel: '',
            labelOption: '',
            sortRule: "sortRule",
            sortScore: {
                crisis_level: {
                    labelNumber: {
                        A: 1000,
                        B: 100,
                        C: 0
                    },
                    levelNumber: {
                        '+': 0,
                        '-': 0
                    }
                },
                time: {
                    labelNumber: {
                        A: 0,
                        B: 0,
                        C: 0
                    },
                    levelNumber: {
                        '+': 0,
                        '-': 0
                    }
                }
            }
        }
    },
    async created() {
        await this.$store.dispatch('fetchHoliday')
        await this.$store.dispatch('fetchSemesterLabel')
        this.labelOption = this.$store.state.semester_label.data
        this.sortRule = this.$route.query.sort_rule ? this.$route.query.sort_rule : "crisis_level"
        this.semesterLabel = this.$route.query.semesterLabel ? this.$route.query.semesterLabel : this.labelOption[0].label
        await this.$store.dispatch('fetchAssignCases')
        await this.$store.dispatch('fetchCounselors')
        await this.$store.dispatch('fetchUnassignCases')
        this.timetable = this.createTimeTable()
    },
    computed: {
        assigningCases: function(){
            return this.unassignCases.filter(cases => cases.status=="assigning")
        },
        counselors() {
            if (this.semesterLabel !== '')
                return this.$store.state.counselors.filter(counselor => counselor.semester_label === this.semesterLabel)
            else
                return this.$store.state.counselors
        }
    },
    mounted() {
        var parentwidth = this.$refs.assignTable.clientWidth
        this.tableWidth = parentwidth
    },
    methods: {
        semesterLabelSelected() {
            this.$router.push({ path: '', query: { semesterLabel: this.semesterLabel } })
            this.reload()
        },
        pushSortRule() {
            this.$router.push({ path: '', query: { sort_rule: this.sortRule } })
            this.reload()
        },
        sortCases(cases) {
            // 算today~create_date並加入score
            const endDate = new Date()
            const msInDay = 1000 * 60 * 60 * 24
            this.sortRule = this.$route.query.sort_rule ? this.$route.query.sort_rule : "crisis_level"

            var labelNumber = this.sortScore[this.sortRule]["labelNumber"]
            var levelNumber = this.sortScore[this.sortRule]["levelNumber"]

            cases.forEach(element => {
                let count = 0
                
                for (let l in labelNumber){
                    if(element.crisis_level.indexOf(l)>=0) count+=labelNumber[l]
                }
                for (let l in levelNumber){
                    if(element.crisis_level.indexOf(l)>=0) count+=levelNumber[l]
                }
                element.score = count
                let startDate = new Date(element.init_consultation_date)
                let dis = Math.ceil(Math.abs(endDate - startDate) / msInDay);
                element.score+=dis
            });
            cases.sort(function (a, b) {
                if (a.score > b.score) {
                    return -1;
                }
                if (a.score < b.score) {
                    return 1;
                }
                return 0;
            });
        },
        createTimeTable() {
            this.unassignCases = _.cloneDeep(this.$store.state.unassignCases)
            this.unassignCases = this.unassignCases.filter((item) =>
                item.semester_label === this.semesterLabel
            )

            this.sortCases(this.unassignCases)

            this.assignCases = _.cloneDeep(this.$store.state.assignCases.data)

            // Slots are keyed by counselor id so same-named counselors stay distinct,
            // and so the scheduler can resolve each slot's employment type / gender.
            this.counselorById = {}
            this.counselors.forEach(counselor => {
                this.counselorById[counselor.id] = {
                    id: counselor.id,
                    name: counselor.name,
                    gender: counselor.gender,
                    employment_type: counselor.employment_type
                }
            })

            let timetable = {}
                // set week days
            for(let offset=8 ; offset>=0 ; offset--) {
                var weekdays = ["U","M","T","W","R","F","S"]
                var today = new Date()
                today.setDate(today.getDate() + offset)
                const offset_date = weekdays[today.getDay()]
                if (offset_date != "U" && offset_date!= "S") {
                    let isHoliday = this.checkHoliday(today)
                    // add dayList
                    this.dayList.push({name: offset_date,offset: offset})
                    var rowAry = {}
                    // set counselors
                    this.counselors.forEach(counselor => {  // get counselors in the day
                        if(counselor.available_time.indexOf(offset_date) >= 0 ){
                            let timeAry = counselor.available_time.split(",")
                            let blockObj = {}
                            for(let t=0 ; t < timeAry.length ; t++){     // get time in the day
                                if( timeAry[t].indexOf(offset_date) >= 0 ) {
                                    let the_time = timeAry[t].substr(timeAry[t].length - 1)
                                    blockObj[the_time] = 'unassign'
                                    if(!isHoliday)
                                        this.emptyTimeList.unshift(`${offset_date}${the_time}-${offset}-${counselor.id}`)
                                }
                            }
                            rowAry[counselor.id] = {
                                counselor_name: counselor.name,
                                employment_type: counselor.employment_type,
                                inSemester: true,
                                block: blockObj
                            }
                        }
                    })
                    timetable[offset] = {
                        offset: offset,
                        rows: rowAry,
                        isHoliday: isHoliday ? true : false
                    }
                }
            }
            // set assigned cases
            if(this.assignCases) {
                this.assignCases.forEach(item => {
                    let fitDay = this.dayList.filter( d => d.name == item.consultation_day)
                    fitDay.forEach( day => {
                        // Historical cases can point at a counselor outside this semester's
                        // grid; synthesise a display-only row for them as before.
                        if(!timetable[day.offset].rows[item.counselor_id])
                            timetable[day.offset].rows[item.counselor_id]= {counselor_name: item.counselor_name, block : {}}
                        let row = timetable[day.offset].rows[item.counselor_id]
                        // check end day & start day
                        if(this.checkRangeDay(day.offset,item.end_consultation_date,item.first_consultation_date,item.status)) {
                            let _item = _.cloneDeep(item)
                            row.block[item.consultation_time] = _item
                            row.block[item.consultation_time].consultation_number = this.countConsultationNumber(this.getDateStr(day.offset), _item.first_consultation_date)
                            this.emptyTimeList = removeEmptyTimeList(this.emptyTimeList,day.name,_item.consultation_time,day.offset,_item.counselor_id)
                        }
                        else if (this.checkReserve(day.offset,item.first_consultation_date)) {
                            let _item = _.cloneDeep(item)
                            row.block[item.consultation_time] = _item
                            row.block[item.consultation_time].consultation_number = 0
                            row.block[item.consultation_time].status= "reserve"
                            this.emptyTimeList = removeEmptyTimeList(this.emptyTimeList,day.name,_item.consultation_time,day.offset,_item.counselor_id)
                        }
                    })
                })
            }
            this.emptyTimeList = clearRepeatTime( _.cloneDeep(this.emptyTimeList))
            // assigning cases
            // get assign method
            if(this.unassignCases.length>0) {
                let root_node = {
                    timeInfo: '',
                    fit_time: fitEmptyTimeList(this.unassignCases[0],this.emptyTimeList,this.counselorById),
                    remain_time: this.emptyTimeList
                }
                this.finalTimeInfo = buildMatchTree(this.unassignCases, root_node, this.counselorById)
                let infoIdx = 0
                // arrange the meeting
                while(this.finalTimeInfo.length>0) {
                    if(this.finalTimeInfo[0] == 'unassign' || this.finalTimeInfo[0]=='undefined') {
                        this.finalTimeInfo.shift()
                    }
                    else {
                        let assingDay = this.finalTimeInfo[0].charAt(0)
                        let assignTime = this.finalTimeInfo[0].charAt(1)
                        let dayOffset = this.finalTimeInfo[0].split('-')[1]
                        let counselorId = this.finalTimeInfo[0].split('-')[2]
                        let counselor = this.counselorById[counselorId]

                        this.unassignCases[infoIdx].status = "assigning"
                        this.unassignCases[infoIdx].consultation_day = assingDay
                        this.unassignCases[infoIdx].consultation_time = assignTime
                        this.unassignCases[infoIdx].counselor_name = counselor.name
                        this.unassignCases[infoIdx].counselor_id = counselor.id
                        this.unassignCases[infoIdx].first_consultation_date = this.getDateStr(dayOffset)
                        this.unassignCases[infoIdx].consultation_number = 0
                        timetable[dayOffset].rows[counselorId].block[assignTime] = _.cloneDeep(this.unassignCases[infoIdx])
                        if (dayOffset < 2) {
                            let nextOffset = parseInt(dayOffset)+7
                            timetable[nextOffset].rows[counselorId].block[assignTime] = _.cloneDeep(this.unassignCases[infoIdx])
                            timetable[nextOffset].rows[counselorId].block[assignTime].consultation_number = 1
                            timetable[nextOffset].rows[counselorId].block[assignTime].isLater = true
                        }
                        this.finalTimeInfo.shift()
                    }
                    infoIdx+=1
                }
            }
            
            setTimeout(() => {
                this.loading = false
            }, "1000")
            return timetable
        },
        getDateStr(offset){
            return dateStrFromOffset(offset)
        },
        // frontend control
        getDatetime(offset){
            var weekdays = ["（日）","（ㄧ）","（二）","（三）","（四）","（五）","（六）"]
            var today = new Date()
            today.setDate(today.getDate() + parseInt(offset))
            var date = today.getFullYear()+' / '+(today.getMonth()+1)+' / '+today.getDate()+'  '+weekdays[today.getDay()]
            return date
        },
        allowDrop(ev) {
            ev.preventDefault()
        },
        drag(ev) {
            // currentTarget is the draggable card itself; target could be a nested
            // tag/label whose id is empty, which would break the drop lookup.
            ev.dataTransfer.setData("text", ev.currentTarget.id)
        },
        crisisBadgeClass(level) {
            if (level && level.indexOf('A') >= 0) return 'crisis-a'
            if (level && level.indexOf('B') >= 0) return 'crisis-b'
            return 'crisis-c'
        },
        // Whether an intern may take this case — driven by the matching rule, so
        // A/B are always 不可派實習生 regardless of the refuse_intern flag.
        internDispatchable(item) {
            return isEligible(item, EMPLOYMENT.INTERN)
        },
        drop(ev) {
            ev.preventDefault()
            var data = ev.dataTransfer.getData("text")
            if(ev.target.classList.contains("unassign-block")) {
                ev.target.appendChild(document.getElementById(data))
            }
            else{
                this.removeTimeblock({id: data.split('-')[1], dis: 'table'})
            }
            // else{
            //     this.$refs.dragBody.appendChild(document.getElementById(data))
            // }
        },
        setDragPos(val) {
            this.dragPos = val
        },
        removeTimeblock({ id, dis}) {
            if(dis == 'table') {
                Object.keys(this.timetable).forEach(offset => {
                    Object.keys(this.timetable[offset].rows).forEach(row => {
                        Object.keys(this.timetable[offset].rows[row].block).forEach(counselor => {
                            if (this.timetable[offset].rows[row].block[counselor].id==id){
                                this.changeCaseStatus(id,'unassign')
                                this.timetable[offset].rows[row].block[counselor] = 'unassign'
                            }
                        })
                    })
                })
            }
            else if(this.dragPos!=''){
                var pos = this.dragPos.split('-')
                if(this.timetable[parseInt(pos[0])+7]) {
                    this.timetable[parseInt(pos[0])+7].rows[pos[1]].block[pos[2]] = 'unassign'
                }
                this.timetable[pos[0]].rows[pos[1]].block[pos[2]] = 'unassign'
            }
        },
        addTimeblock(id,tIdx,row,col) {
            var day = this.dayList.find(e => e.offset == tIdx)
            for(let i=0;i<this.unassignCases.length;i++){
                if(this.unassignCases[i].id == id){
                    // `row` is the row key = counselor id. Manual drops are an explicit
                    // override, so they bypass the eligibility rules on purpose.
                    this.timetable[tIdx].rows[row].block[col] = this.unassignCases[i]
                    this.unassignCases[i].status = "assigning"
                    this.unassignCases[i].counselor_name = this.counselorById[row]
                        ? this.counselorById[row].name
                        : this.timetable[tIdx].rows[row].counselor_name
                    this.unassignCases[i].counselor_id = parseInt(row)
                    this.unassignCases[i].consultation_day = day.name
                    this.unassignCases[i].consultation_time = col
                    this.unassignCases[i].first_consultation_date = this.getDateStr(tIdx)
                    if(this.timetable[tIdx+7]) {
                        if(this.timetable[tIdx+7].rows[row].block[col]!="unassign") {
                            this.changeCaseStatus(this.timetable[tIdx+7].rows[row].block[col].id,"unassign")
                        }
                        this.timetable[tIdx+7].rows[row].block[col] = _.cloneDeep(this.unassignCases[i])
                        this.timetable[tIdx+7].rows[row].block[col].consultation_number = 1
                        this.timetable[tIdx+7].rows[row].block[col].isLater = true
                    }
                    return
                }
            }
        },
        changeCaseStatus(id,status) {
            let unassignCase = this.unassignCases.find(e => e.id == id)
            if(unassignCase) {
                unassignCase.status = status
            }
        },
        putCase(id,body) {
            let data = {}
            if(body.status == "closed"){
                data = {
                    status: body.status,
                    end_consultation_date: body.end_consultation_date 
                }
            }
            else if(body.status == "unassign"){
                data = {
                    status: body.status
                }
            }
            else {
                data = {
                    status: body.status,
                    consultation_day: body.consultation_day,
                    consultation_time: body.consultation_time,
                    counselor_id: body.counselor_id,
                    counselor_name: body.counselor_name,
                    first_consultation_date: body.first_consultation_date
                }
            }
                
            this.$http.put("/api/cases/"+id,data)
            .then(() => {
                // this.$store.dispatch('fetchAssignCases')
            })
            .catch((error) => {
                console.error(error)
            });
        },
        submitChange() {
            let assigningCases = _.cloneDeep(this.assigningCases)
            for(let i=0;i<this.assigningCases.length;i++) {
                assigningCases[i].status = "assign"
                this.putCase(assigningCases[i].id,assigningCases[i])
            }
            this.dialogVisible = true
        },
        downloadXLS() {
            return this.convertCases(_.cloneDeep(this.assigningCases))
        },
        downloadCSV() {
            csvDownload(this.convertCases(_.cloneDeep(this.assigningCases)), this.json_fields)
        },
        convertCases(cases) {
            return cases.map(caseItem => ({
                ...caseItem,
                consultation_datetime: formatConsultationDateTime(caseItem, this.days, this.times),
                init_consultation_date: this.convertUTCtoStr(caseItem.init_consultation_date)
            }));
        },
        handleClose() {
            // change timetable result
            let assigningCases = _.cloneDeep(this.assigningCases)
            for(let i=0;i<assigningCases.length;i++) {
                Object.keys(this.timetable).forEach(offset => {
                    Object.keys(this.timetable[offset].rows).forEach(row => {
                        Object.keys(this.timetable[offset].rows[row].block).forEach(counselor => {
                            if (this.timetable[offset].rows[row].block[counselor].id==assigningCases[i].id){
                                this.timetable[offset].rows[row].block[counselor].status = 'assign'
                                this.timetable[offset].rows[row].block[counselor].consultation_number = 1
                            }
                        })
                    })
                })
            }
            this.unassignCases = this.unassignCases.filter(e => e.status == 'unassign')
        },
        endCase(data) {
            let endCase = data
            endCase.status = "closed"
            endCase.end_consultation_date = this.getDateStr(endCase.offset)
            this.putCase(endCase.id,endCase)
            this.removeTimeblock({id: data.id})
        },
        returnCase(data) {
            let returnCase = data
            returnCase.status = "unassign"
            returnCase.consultation_number = 0
            this.putCase(returnCase.id,returnCase)
            this.removeTimeblock({id: data.id, dis: 'table'})
            this.unassignCases.push(data)
        },
        getLabelColor(label) {
            const option = this.labelOption.find(opt => opt.label === label)
            return option ? option.color : '#409EFF'
        },
        getStyleForLabel(label) {
            const color = this.getLabelColor(label)
            return `background-color: ${color}44; color: ${color}; border: 1px solid ${color}`
        }
    }
}
</script>
