// Employment-type / gender matching rules for the 初排 auto-assignment.
// Pure functions — no Vue, no `this` — so they are unit-tested in isolation and
// injected into the scheduling algorithm's `fitEmptyTimeList` seam.
//
// Spec (see PLAN.jerry-counselor-attributes-and-priority-assignment.md):
//   crisis group A/B  -> eligible 專任/兼任 (no intern);   preference 兼任 > 專任
//   crisis group C, may take intern -> all three;          preference 實習生 > 專任 > 兼任
//   crisis group C, refuses intern  -> 專任/兼任 (no intern); preference 兼任 > 專任 (比照 AB)
//   gender: soft — a case's preferred_gender ("男"/"女"/"不限"/empty) is a
//           preference, never a hard filter.

export const EMPLOYMENT = {
  FULL: '專任',   // full-time
  PART: '兼任',   // part-time
  INTERN: '實習生', // intern
}

// Preference tables: lower number = more preferred. A type absent from the table
// is INELIGIBLE for that case (rank Infinity). NULL/unknown employment types are
// therefore never eligible — un-backfilled counselors sit out until edited.
const PREF_AB = { [EMPLOYMENT.PART]: 0, [EMPLOYMENT.FULL]: 1 }
const PREF_C_INTERN_OK = { [EMPLOYMENT.INTERN]: 0, [EMPLOYMENT.FULL]: 1, [EMPLOYMENT.PART]: 2 }
const PREF_C_REFUSE_INTERN = { [EMPLOYMENT.PART]: 0, [EMPLOYMENT.FULL]: 1 }

// A+/A/A- -> 'A'; B+/B/B- -> 'B'; everything else (C) -> 'C'.
// Matches the substring logic used by the existing sortCases scoring.
export function crisisGroup(crisisLevel) {
  const s = crisisLevel || ''
  if (s.indexOf('A') >= 0) return 'A'
  if (s.indexOf('B') >= 0) return 'B'
  return 'C'
}

function refusesIntern(caseItem) {
  const v = caseItem.refuse_intern
  return v === true || v === 1 || v === '1'
}

function preferenceTable(caseItem) {
  const group = crisisGroup(caseItem.crisis_level)
  if (group === 'A' || group === 'B') return PREF_AB
  return refusesIntern(caseItem) ? PREF_C_REFUSE_INTERN : PREF_C_INTERN_OK
}

// The set of employment types this case may be assigned to (hard filter).
export function eligibleTypes(caseItem) {
  return new Set(Object.keys(preferenceTable(caseItem)))
}

// Preference rank for a given employment type (lower = more preferred);
// Infinity means ineligible.
export function typePreferenceRank(caseItem, employmentType) {
  const table = preferenceTable(caseItem)
  return Object.prototype.hasOwnProperty.call(table, employmentType)
    ? table[employmentType]
    : Infinity
}

// Convenience: is this employment type allowed for this case at all?
export function isEligible(caseItem, employmentType) {
  return typePreferenceRank(caseItem, employmentType) !== Infinity
}

// Soft gender preference: true when the case has no specific preference
// (empty/"不限"/null) or the counselor's gender matches it.
export function genderMatches(caseItem, counselor) {
  const pref = caseItem.preferred_gender
  if (!pref || pref === '不限') return true
  return pref === counselor.gender
}
