// Pure core of the 初排 (initial-schedule) auto-assignment algorithm, extracted
// from assigning.vue so it can be unit-tested and so the counselor-attributes
// feature can inject employment-type/gender eligibility at the
// `fitEmptyTimeList` seam without touching the Vue component.
//
// Slot tokens are strings shaped like "M1-3-308" = "<day><time>-<offset>-<id>".
// Keying on the counselor id (not the name) keeps two same-named counselors from
// collapsing into one row.
// available_time is a comma string like "M1,T4,R2".

import { isEligible, typePreferenceRank, genderMatches } from './matchingRules'

export function counselorIdFromToken(timeInfo) {
  return timeInfo.split('-')[2]
}

// Keep only slots that are (1) inside the case's available_time and (2) staffed
// by a counselor whose employment type is eligible for the case — an unknown or
// un-backfilled counselor is eligible for nobody, so their slots drop out.
// Survivors are sorted most-preferred-first (employment type, then gender) so
// that `fit_time[0]` is the best pick where the search is otherwise indifferent.
export function fitEmptyTimeList(caseItem, remain_time, counselorById = {}) {
  const available_time = caseItem.available_time || ''
  // A designated case is HARD-pinned to that counselor: only their slots are
  // eligible. Eligibility (employment type) still applies on top, so an
  // ineligible designation (e.g. an A/B case → an intern) leaves no slots and
  // the case stays unassigned — it is never reassigned to someone else.
  const designatedId = caseItem.designated_counselor_id
  const hasDesignation = designatedId !== null && designatedId !== undefined && designatedId !== ''
  const fits = remain_time.filter(timeInfo => {
    if (available_time.indexOf(timeInfo.split('-')[0]) < 0) return false
    const slotCounselorId = counselorIdFromToken(timeInfo)
    if (hasDesignation && String(slotCounselorId) !== String(designatedId)) return false
    const counselor = counselorById[slotCounselorId]
    if (!counselor) return false
    return isEligible(caseItem, counselor.employment_type)
  })
  // Sort is soft: it only orders slots that the hard filter already accepted.
  return fits
    .map((timeInfo, idx) => ({ timeInfo, idx }))
    .sort((a, b) => {
      const ca = counselorById[counselorIdFromToken(a.timeInfo)]
      const cb = counselorById[counselorIdFromToken(b.timeInfo)]
      const rank = typePreferenceRank(caseItem, ca.employment_type) -
        typePreferenceRank(caseItem, cb.employment_type)
      if (rank !== 0) return rank
      const gender = (genderMatches(caseItem, ca) ? 0 : 1) - (genderMatches(caseItem, cb) ? 0 : 1)
      if (gender !== 0) return gender
      return a.idx - b.idx // stable: preserve the original slot order otherwise
    })
    .map(entry => entry.timeInfo)
}

// Remove the "+7 day" recurring-week duplicate of each slot from the list.
// NOTE: mutates and returns `list` (behaviour preserved from the original).
export function clearRepeatTime(list) {
  list.forEach(item => {
    let labels = item.split('-')
    labels[1] = parseInt(labels[1]) + 7
    let idx = list.indexOf(labels.join('-'))
    if (idx >= 0) {
      list.splice(idx, 1)
    }
  })
  return list
}

// Remove one slot from a copy of `_ary`. Either pass an explicit `timeInfo`
// token, or the (day,time,offset,counselorId) parts to reconstruct it.
export function removeEmptyTimeList(_ary, day, time, offset, counselorId, timeInfo = null) {
  let ary = []
  let i = -1
  while (++i < _ary.length) {
    ary[i] = _ary[i]
  }
  var index
  if (!timeInfo)
    index = ary.indexOf(`${day}${time}-${offset}-${counselorId}`)
  else
    index = ary.indexOf(timeInfo)
  if (index > -1) {
    ary.splice(index, 1)
  }
  return Object.values(ary)
}

// Greedy/backtracking search that walks the sorted cases and picks, for each,
// a slot that maximises how many remaining cases can still be placed. Returns
// the chosen assignment as an array of slot tokens (with 'unassign' for cases
// that could not be placed), in case order.
//
// Faithful port of the original recursive `makeTree`: it explores every branch
// whose look-ahead improves `maxFit` and the LAST leaf reached wins — the
// closure `finalTimeInfo` mirrors the original `this.finalTimeInfo` overwrite.
// Maximising placement count stays the primary objective; the preference order
// baked into `fitEmptyTimeList` only decides ties.
export function buildMatchTree(unassignCases, rootNode, counselorById = {}) {
  let finalTimeInfo = null

  function recurse(nodes, caseIdx) {
    if (unassignCases[caseIdx + 1]) {
      if (nodes.fit_time.length > 0) {
        let maxFit = 0
        nodes.fit_time.forEach(timeInfo => {
          let _fit_time = fitEmptyTimeList(
            unassignCases[caseIdx + 1],
            removeEmptyTimeList(nodes.remain_time, 0, 0, 0, 0, timeInfo),
            counselorById
          )
          if (_fit_time.length > maxFit) {
            maxFit = _fit_time.length
            recurse({
              timeInfo: nodes.timeInfo + timeInfo + ',',
              remain_time: removeEmptyTimeList(nodes.remain_time, 0, 0, 0, 0, timeInfo),
              fit_time: _fit_time,
            }, caseIdx + 1)
          }
        })
        if (maxFit == 0) {
          let timeInfo = nodes.fit_time[0]
          recurse({
            timeInfo: nodes.timeInfo + timeInfo + ',',
            remain_time: removeEmptyTimeList(nodes.remain_time, 0, 0, 0, 0, timeInfo),
            fit_time: fitEmptyTimeList(
              unassignCases[caseIdx + 1],
              removeEmptyTimeList(nodes.remain_time, 0, 0, 0, 0, timeInfo),
              counselorById
            ),
          }, caseIdx + 1)
        }
      } else {
        recurse({
          timeInfo: nodes.timeInfo + 'unassign' + ',',
          remain_time: nodes.remain_time,
          fit_time: fitEmptyTimeList(unassignCases[caseIdx + 1], nodes.remain_time, counselorById),
        }, caseIdx + 1)
      }
    } else {
      finalTimeInfo = (nodes.timeInfo + nodes.fit_time[0]).split(',')
    }
  }

  recurse(rootNode, 0)
  return finalTimeInfo
}
